INSERT INTO refunds (payment_id, amount_minor, reason, created_at)
VALUES (7, 900, 'customer_request', now()) RETURNING refund_id;
SELECT count(*) FROM merchant_fee_schedules;
SELECT now() AS before_the_mistake;
SELECT pg_sleep(1);
DELETE FROM merchant_fee_schedules;          -- the cleanup script forgot its WHERE
SELECT pg_switch_wal();                      -- close the segment so the archiver copies it now

-- restore: docker compose -f env/postgres-ha.yml --profile pitr exec restore psql -U sfz -d course
SELECT count(*) FROM merchant_fee_schedules;
SELECT refund_id, amount_minor FROM refunds ORDER BY refund_id DESC LIMIT 2;
SELECT pg_is_in_recovery();

